+'use strict';
+const DATA = __DATA_JSON__;
+const METRICS = __METRICS_JSON__;
+const ROWS = DATA.rows, N = ROWS.length;
+const GC = METRICS.G, MASS = METRICS.masses;
+const COLS = ['#e5484d', '#3ea6ff', '#ffc53d'];
+const NAMES = ['星 1', '星 2', '星 3'];
+const E0 = METRICS.initial_energy, L0 = METRICS.initial_angular_momentum;
+const WALL_SECONDS = 40;
