+    pe -= GC * MASS[i] * MASS[j] / d;
+  }
+  return ke + pe;
+}
+function angOf(row){
+  let l = 0;
+  for (let i = 0; i < 3; i++) l += MASS[i] * (px(row, i) * vy(row, i) - py(row, i) * vx(row, i));
+  return l;
