  }

  var COLORS = {
    planned: '#94a3b8',
    actual: '#1d4ed8',
    good: '#0f766e',
    defect: '#b91c1c',
    energy: '#b45309',
    quality: '#7c3aed',
    grid: '#dbe3ec',
    axis: '#475569',
    target: '#0f172a'
