  }

  function noData(w, h, msg) {
    return '<svg viewBox="0 0 ' + w + ' ' + h + '" width="' + w + '" height="' + h +
      '" role="img" aria-label="' + esc(msg) + '" font-family="inherit">' +
      '<rect x="0.5" y="0.5" width="' + (w - 1) + '" height="' + (h - 1) + '" fill="#f8fafc" stroke="' + COLORS.grid + '"/>' +
      txt(w / 2, h / 2, msg, { anchor: 'middle', size: 13, fill: '#64748b' }) + '</svg>';
  }

  /* 图 1：产线计划 vs 实际（横向分组条；中文标签在窄屏更易读） */
  function chartLineCompare(lines, w) {
    if (!lines.length) return noData(w, 150, '当前筛选没有生产记录，无法绘制产线对比图');
    var labelW = w < 560 ? 74 : 100;
    var rowH = w < 560 ? 64 : 68;
    var top = 30, bottom = 34;
    var h = top + bottom + rowH * lines.length;
    var max = 0;
    lines.forEach(function (l) {
      if (isNum(l.planned)) max = Math.max(max, l.planned);
      if (isNum(l.actual)) max = Math.max(max, l.actual);
    });
    var t = niceTicks(max, 4);
    var plotW = Math.max(w - labelW - (w < 560 ? 60 : 78), 40);
    var s = '<svg viewBox="0 0 ' + w + ' ' + h + '" width="' + w + '" height="' + h +
      '" role="img" aria-label="产线计划产量与实际产量对比条形图，单位吨" font-family="inherit">';
    s += '<rect x="0" y="0" width="' + w + '" height="' + h + '" fill="#ffffff"/>';
    for (var v = 0; v <= t.top + 1e-9; v += t.step) {
      var gx = labelW + plotW * (v / t.top);
      s += '<line x1="' + gx + '" y1="' + top + '" x2="' + gx + '" y2="' + (h - bottom + 6) + '" stroke="' + COLORS.grid + '" stroke-width="1"/>';
      s += txt(gx, h - bottom + 20, FMT.int(v), { anchor: 'middle', size: 10 });
    }
    s += txt(labelW + plotW / 2, h - 4, '产量（吨）', { anchor: 'middle', size: 11, fill: '#64748b' });
    s += '<rect x="' + Math.max(w - 158, labelW) + '" y="7" width="10" height="10" fill="' + COLORS.planned + '"/>' +
      txt(Math.max(w - 158, labelW) + 14, 16, '计划', { size: 11 }) +
      '<rect x="' + Math.max(w - 96, labelW + 60) + '" y="7" width="10" height="10" fill="' + COLORS.actual + '"/>' +
      txt(Math.max(w - 96, labelW + 60) + 14, 16, '实际', { size: 11 });
    lines.forEach(function (l, i) {
      var y0 = top + i * rowH;
      var bw1 = isNum(l.planned) ? Math.max(plotW * (l.planned / t.top), 0) : 0;
      var bw2 = isNum(l.actual) ? Math.max(plotW * (l.actual / t.top), 0) : 0;
      s += txt(0, y0 + 20, l.line, { size: 12, weight: '600', fill: '#0f172a' });
      s += '<rect x="' + labelW + '" y="' + (y0 + 10) + '" width="' + bw1 + '" height="15" rx="2" fill="' + COLORS.planned + '"/>';
      s += '<rect x="' + labelW + '" y="' + (y0 + 29) + '" width="' + bw2 + '" height="15" rx="2" fill="' + COLORS.actual + '"/>';
      s += txt(labelW + bw1 + 5, y0 + 22, isNum(l.planned) ? FMT.int(l.planned) : EMPTY, { size: 10 });
      s += txt(labelW + bw2 + 5, y0 + 41, isNum(l.actual) ? FMT.int(l.actual) : EMPTY, { size: 10, weight: '600', fill: COLORS.actual });
      s += txt(0, y0 + 41, '第 ' + l.rank + ' 名', { size: 10, fill: '#64748b' });
      s += txt(0, y0 + 56, '达成 ' + FMT.pct(l.attainment), { size: 10, fill: '#64748b' });
    });
    s += '</svg>';
    return s;
  }

  /* 图 2：每日产量趋势（计划 vs 实际折线） */
  function chartTrend(daily, w) {
    if (!daily.length) return noData(w, 200, '当前筛选没有生产记录，无法绘制每日趋势图');
    var top = 28, bottom = 50, left = w < 560 ? 42 : 56, right = w < 560 ? 10 : 18;
    var plotH = 200, h = top + bottom + plotH;
    var max = 0;
    daily.forEach(function (d) {
      if (isNum(d.planned)) max = Math.max(max, d.planned);
      if (isNum(d.actual)) max = Math.max(max, d.actual);
    });
    var t = niceTicks(max, 4);
    var plotW = Math.max(w - left - right, 40);
    var stepX = daily.length > 1 ? plotW / (daily.length - 1) : 0;
    function X(i) { return left + (daily.length > 1 ? i * stepX : plotW / 2); }
    function Y(v) { return top + plotH - (isNum(v) ? v : 0) / t.top * plotH; }
    var s = '<svg viewBox="0 0 ' + w + ' ' + h + '" width="' + w + '" height="' + h +
      '" role="img" aria-label="每日计划与实际产量趋势折线图，单位吨" font-family="inherit">';
    s += '<rect x="0" y="0" width="' + w + '" height="' + h + '" fill="#ffffff"/>';
    for (var v = 0; v <= t.top + 1e-9; v += t.step) {
      var gy = Y(v);
      s += '<line x1="' + left + '" y1="' + gy + '" x2="' + (w - right) + '" y2="' + gy + '" stroke="' + COLORS.grid + '"/>';
      s += txt(left - 7, gy + 4, FMT.int(v), { anchor: 'end', size: 10 });
    }
    s += txt(2, top - 8, '吨', { size: 10, fill: '#64748b' });
    function series(key, color, dash) {
      var pts = [];
      daily.forEach(function (d, i) { if (isNum(d[key])) pts.push(X(i) + ',' + Y(d[key])); });
      if (pts.length < 2) return '';
      return '<polyline points="' + pts.join(' ') + '" fill="none" stroke="' + color +
        '" stroke-width="2.5" stroke-linejoin="round"' + (dash ? ' stroke-dasharray="5 4"' : '') + '/>';
    }
    s += series('planned', COLORS.planned, true);
    s += series('actual', COLORS.actual, false);
    daily.forEach(function (d, i) {
      if (isNum(d.planned)) s += '<circle cx="' + X(i) + '" cy="' + Y(d.planned) + '" r="2.8" fill="#ffffff" stroke="' + COLORS.planned + '" stroke-width="2"/>';
      if (isNum(d.actual)) s += '<circle cx="' + X(i) + '" cy="' + Y(d.actual) + '" r="3.2" fill="' + COLORS.actual + '"/>';
    });
    var every = (daily.length > 8 && w < 620) ? 2 : 1;
    daily.forEach(function (d, i) {
      if (i % every !== 0) return;
      s += txt(X(i), h - bottom + 18, d.date.slice(5), { anchor: 'middle', size: 10 });
    });
    s += txt(w / 2, h - 6, '日期（月-日，2026 年合成样本）', { anchor: 'middle', size: 10, fill: '#64748b' });
    s += '<rect x="' + Math.max(w - 150, left) + '" y="6" width="10" height="10" fill="' + COLORS.planned + '"/>' +
      txt(Math.max(w - 150, left) + 14, 15, '计划', { size: 11 }) +
      '<rect x="' + Math.max(w - 88, left + 50) + '" y="6" width="10" height="10" fill="' + COLORS.actual + '"/>' +
      txt(Math.max(w - 88, left + 50) + 14, 15, '实际', { size: 11 });
    s += '</svg>';
    return s;
  }

  /* 图 3：产线能耗 / 品质（柱 + 目标虚线标记），mode = 'energy' | 'quality' */
  function chartLineMetric(lines, w, mode) {
    var isEnergy = mode === 'energy';
    var unit = isEnergy ? 'kWh/吨' : '%';
    var title = isEnergy ? '单位电耗 = 电耗合计 / 同范围实际产量合计' : '加权良品率 = 合格合计 / 实际合计';
    var rows = (lines || []).filter(function (l) { return isNum(isEnergy ? l.specific : l.quality); });
    if (!rows.length) return noData(w, 200, '当前筛选下该指标没有可计算记录（电耗未记录或实际产量为 0）');
    var top = 28, bottom = 52, left = w < 560 ? 42 : 56, right = 10;
    var plotH = 190, h = top + bottom + plotH;
    var vals = rows.map(function (l) { return isEnergy ? l.specific : l.quality; });
    var tvs = rows.map(function (l) { return isEnergy ? l.targetEnergy : l.targetQuality; }).filter(isNum);
    var hi = Math.max.apply(null, vals.concat(tvs));
    var lo = Math.min.apply(null, vals.concat(tvs));
    var base, cap;
    if (isEnergy) { base = 0; cap = niceTicks(hi * 1.15, 4).top; }
    else { base = Math.max(0, Math.floor((lo - 1) * 2) / 2); cap = Math.ceil(hi + 1); }
    var span = (cap - base) || 1;
    var t = niceTicks(span, 4);
    var plotW = Math.max(w - left - right, 40);
    function Y(v) { return top + plotH - (v - base) / span * plotH; }
    var s = '<svg viewBox="0 0 ' + w + ' ' + h + '" width="' + w + '" height="' + h +
      '" role="img" aria-label="' + esc(title + '，单位' + unit + '，含产线目标对照') + '" font-family="inherit">';
    s += '<rect x="0" y="0" width="' + w + '" height="' + h + '" fill="#ffffff"/>';
    for (var v = base; v <= cap + 1e-9; v += t.step) {
      var gy = Y(v);
      s += '<line x1="' + left + '" y1="' + gy + '" x2="' + (w - right) + '" y2="' + gy + '" stroke="' + COLORS.grid + '"/>';
      s += txt(left - 7, gy + 4, FMT.num(v, Math.abs(t.step) < 1 ? 1 : 0), { anchor: 'end', size: 10 });
    }
    s += txt(2, top - 8, unit, { size: 10, fill: '#64748b' });
    var band = plotW / rows.length;
    var bw = Math.min(band * 0.5, 66);
    var color = isEnergy ? COLORS.energy : COLORS.quality;
    rows.forEach(function (l, i) {
      var val = isEnergy ? l.specific : l.quality;
      var tgt = isEnergy ? l.targetEnergy : l.targetQuality;
      var cx = left + band * i + band / 2;
      var ok = isNum(tgt) ? (isEnergy ? val <= tgt : val >= tgt) : null;
      s += '<rect x="' + (cx - bw / 2) + '" y="' + Y(val) + '" width="' + bw +
        '" height="' + Math.max(top + plotH - Y(val), 1) + '" rx="2" fill="' + color +
        '" opacity="' + (ok === false ? '1' : '0.8') + '"/>';
      s += txt(cx, Y(val) - 6, FMT.num(val, 2), { anchor: 'middle', size: w < 560 ? 10 : 12, weight: '600', fill: color });
      if (isNum(tgt)) {
        var ty = Y(tgt);
        s += '<line x1="' + (cx - bw / 2 - 5) + '" y1="' + ty + '" x2="' + (cx + bw / 2 + 5) + '" y2="' + ty +
          '" stroke="' + COLORS.target + '" stroke-width="2" stroke-dasharray="4 3"/>';
        s += txt(cx, top + plotH + 34, '目标 ' + FMT.num(tgt, 2), { anchor: 'middle', size: 9, fill: '#64748b' });
      }
      s += txt(cx, top + plotH + 17, l.line, { anchor: 'middle', size: w < 560 ? 10 : 11, weight: '600', fill: '#0f172a' });
    });
    s += txt(w / 2, h - 3, title + (isEnergy ? '' : '（纵轴从 ' + FMT.num(base, 1) + ' % 起，非零基线）'),
      { anchor: 'middle', size: 10, fill: '#64748b' });
    s += '</svg>';
    return s;
  }

  /* 有数据依据的改进建议，全部来自当前筛选范围内可计算的指标 */
  function suggestions(allRows, rows, lines, meta) {
    var out = [];
    if (!rows.length) {
      out.push({ tone: 'warn', title: '当前筛选没有记录',
        text: '所选产线、班次与日期范围内没有生产记录，因此良品率、达成率与单位电耗均不计算（不显示 0，也不显示虚构数值）。请放宽条件或点击“重置筛选”。' });
      return out;
    }
    var full = aggregate(allRows);
    var below = lines.filter(function (l) { return isNum(l.gapQuality) && l.gapQuality < 0; });
    if (below.length) {
      var b = below[0];
      out.push({ tone: 'risk', title: '品质未达标：' + b.line + ' ' + FMT.pct(b.quality) + '，差目标 ' + FMT.num(b.gapQuality, 2) + ' 个百分点',
        text: '该线在当前范围内不良产量 ' + FMT.int(b.defective) + ' 吨，是未达 Excel 良品率目标 ' + FMT.pct(b.targetQuality) +
          ' 的产线。建议按班次与产品复盘该线调质、制粒参数与筛网/环模磨损记录，把加权良品率拉回目标以上。' });
    }
    var lowAttain = lines.filter(function (l) { return isNum(l.attainment); })
      .sort(function (a, c) { return a.attainment - c.attainment; })[0];
    if (lowAttain) {
      out.push({ tone: 'risk', title: '达成最低：' + lowAttain.line + ' ' + FMT.pct(lowAttain.attainment) + '，目标 ' + FMT.pct(lowAttain.targetAttainment) + '，差 ' + FMT.num(lowAttain.gapAttainment, 2) + ' 个百分点',
        text: '该线已知停机 ' + FMT.int(lowAttain.downtime) + ' 分钟' +
          (lowAttain.zeroRows ? '，其中 ' + lowAttain.zeroRows + ' 条零产量记录（' + lowAttain.zeroIds.join('、') + '）' : '') +
          '；计划 ' + FMT.int(lowAttain.planned) + ' 吨、实际 ' + FMT.int(lowAttain.actual) + ' 吨，缺口 ' +
          FMT.int((lowAttain.planned || 0) - (lowAttain.actual || 0)) + ' 吨。建议对长停班次做停机归因与换产计划复核。' });
    }
    var shifts = byShift(rows);
    var night = shifts.filter(function (x) { return x.shift === '夜班'; })[0];
    var day = shifts.filter(function (x) { return x.shift === '白班'; })[0];
    if (night && day && isNum(night.downtime) && isNum(day.downtime)) {
      out.push({ tone: 'note', title: '夜班已知停机 ' + FMT.int(night.downtime) + ' 分 vs 白班 ' + FMT.int(day.downtime) + ' 分',
        text: '夜班达成率 ' + FMT.pct(night.attainment) + '，白班 ' + FMT.pct(day.attainment) +
          '（各自按合计产量加权，不做行平均）。建议把夜班作为停机与换产改善的优先窗口，并核查交接班与巡检记录完整性。' });
    }
    var eLines = lines.filter(function (l) { return isNum(l.specific); });
    var worstE = eLines.slice().sort(function (a, c) { return c.specific - a.specific; })[0];
    var bestE = eLines.slice().sort(function (a, c) { return a.specific - c.specific; })[0];
    if (worstE && bestE && worstE.line !== bestE.line) {
      out.push({ tone: 'note', title: '单位电耗差异：' + worstE.line + ' ' + FMT.num(worstE.specific, 2) + ' vs ' + bestE.line + ' ' + FMT.num(bestE.specific, 2) + ' kWh/吨',
        text: worstE.line + ' 相对目标 ' + FMT.num(worstE.targetEnergy, 2) + ' kWh/吨' +
          (isNum(worstE.gapEnergy) ? (worstE.gapEnergy <= 0 ? ' 仍优 ' + FMT.num(Math.abs(worstE.gapEnergy), 2) : ' 超出 ' + FMT.num(worstE.gapEnergy, 2)) : '') +
          ' kWh/吨。建议对标低能耗产线的开机时序与空转管控，优先压缩高能耗产线的非生产用电；单位电耗只覆盖电耗已记录且实际产量>0 的 ' +
          FMT.int(worstE.energyRows) + ' 条记录。' });
    }
    var dq = [];
    if (full.missingDowntime) dq.push(full.missingDowntime + ' 条停机分钟未记录');
