    if (dq.length) {
      out.push({ tone: 'warn', title: '数据完整性：' + dq.join('、') + '（去重后 ' + FMT.int(full.records) + ' 条中）',
        text: '按口径说明保留缺失、不填零，因此“已知停机”和“单位电耗”只覆盖已记录部分，真实值可能被低估。建议补齐计量点数据后重算，并在报表标注采集覆盖率。' });
    }
    if (meta && isNum(meta.duplicateRows) && meta.duplicateRows > 0) {
      out.push({ tone: 'warn', title: '重复记录已剔除 ' + FMT.int(meta.duplicateRows) + ' 条',
        text: '编号 ' + (meta.duplicateIds || []).join('、') + ' 在原始表中出现两次且逐列相同，已按“保留首条”去重（' +
          FMT.int(meta.sourceRows) + ' → ' + FMT.int(meta.uniqueRows) + ' 条）。建议在采集端为记录编号加唯一约束，避免重复入库虚增产量与能耗。' });
    }
    out.push({ tone: 'note', title: '产销衔接与口径边界',
      text: '发货区收入按逐条“发货量 × 单价”求和，收入不等于利润，也不等于回款；发货源数据没有班次维度，因此不能按班次拆分发货。全部数值来自合成验收样本，仅用于验收演示。' });
