  font-size:15px;line-height:1.6;-webkit-text-size-adjust:100%;overflow-x:hidden;
}
.wrap{max-width:1180px;margin:0 auto;padding:16px 14px 44px}
h1{font-size:clamp(19px,4.4vw,27px);margin:10px 0 6px;letter-spacing:.2px}
h2{font-size:clamp(16px,3.4vw,19px);margin:0 0 4px}
h3{font-size:15px;margin:16px 0 6px}
p{margin:6px 0}
.small{font-size:12.5px;color:var(--muted)}
code,.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.94em}
a{color:var(--brand)}
.syn-banner{
  background:var(--warn-soft);border:1.5px solid #f0c674;border-left:6px solid var(--warn);
  border-radius:10px;padding:11px 13px;margin:2px 0 14px;
}
.syn-banner b{color:#7c2d12}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px;margin:14px 0;box-shadow:0 1px 2px rgba(15,23,42,.05)}
.card-head{display:flex;flex-wrap:wrap;gap:6px;align-items:baseline;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:8px;margin-bottom:10px}
.card-head .small{max-width:62ch}
.badge{display:inline-block;font-size:11.5px;font-weight:700;letter-spacing:.4px;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:#f8fafc;color:var(--ink2)}
.badge.syn{background:#fef3c7;border-color:#eab308;color:#7c2d12}
.badge.brand{background:var(--brand-soft);border-color:#bfdbfe;color:#1e40af}
.meta-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-top:10px}
.meta-list div{border-left:3px solid var(--line);padding-left:9px;font-size:13px;color:var(--ink2)}
.meta-list span{display:block;color:var(--muted);font-size:11.5px;letter-spacing:.3px}
.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}
.field label{display:block;font-size:12px;font-weight:600;color:var(--ink2);margin-bottom:3px}
select,input[type=date]{
  width:100%;font:inherit;font-size:14px;padding:8px 9px;border:1px solid #cbd5e1;border-radius:8px;
  background:#fff;color:var(--ink);min-height:40px;
}
select:focus-visible,input:focus-visible,button:focus-visible,a:focus-visible,th[role=button]:focus-visible{outline:3px solid #93c5fd;outline-offset:1px}
.btn-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;align-items:center}
button{
  font:inherit;font-size:14px;font-weight:600;padding:9px 14px;border-radius:8px;cursor:pointer;
  border:1px solid #cbd5e1;background:#fff;color:var(--ink);min-height:40px;
}
button:hover{border-color:var(--brand);color:var(--brand)}
button.primary{background:var(--brand);border-color:var(--brand);color:#fff}
button.primary:hover{background:#1e40af;color:#fff}
.status{font-size:13px;color:var(--ink2);margin-top:8px;min-height:20px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(158px,1fr));gap:10px}
.kpi{background:#fff;border:1px solid var(--line);border-radius:11px;padding:11px 12px}
.kpi .k-label{font-size:12px;color:var(--muted);letter-spacing:.3px}
.kpi .k-value{font-size:clamp(19px,4.6vw,25px);font-weight:700;line-height:1.25;margin-top:2px;font-variant-numeric:tabular-nums}
.kpi .k-unit{font-size:12px;font-weight:600;color:var(--muted);margin-left:3px}
.kpi .k-note{font-size:11.5px;color:var(--muted);margin-top:3px}
.kpi.hl{border-color:#bfdbfe;background:linear-gradient(180deg,#f8fbff,#fff)}
.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}
.scroll-x{overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%}
.table-scroll{max-height:430px;overflow:auto;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:13.5px}
caption{caption-side:top;text-align:left;font-size:12.5px;color:var(--muted);padding:0 0 6px}
th,td{padding:7px 9px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
th:first-child,td:first-child,th.tl,td.tl{text-align:left}
thead th{position:sticky;top:0;background:#f8fafc;z-index:2;font-size:12.5px;color:var(--ink2);border-bottom:1.5px solid #cbd5e1}
th[role=button]{cursor:pointer}
th[role=button]:hover{color:var(--brand)}
tbody tr:hover{background:#f8fafc}
tr.zero-row td{background:var(--warn-soft)}
.miss{color:#94a3b8;font-style:italic;font-size:12px}
.pos{color:var(--ok);font-weight:700}
.neg{color:var(--risk);font-weight:700}
.tag{display:inline-block;font-size:11px;padding:1px 6px;border-radius:6px;background:#f1f5f9;color:var(--ink2);border:1px solid var(--line)}
.empty{padding:22px 14px;text-align:center;color:var(--ink2);background:#f8fafc;border:1px dashed #cbd5e1;border-radius:10px;font-size:13.5px}
.chart svg{display:block;max-width:100%;height:auto;margin:0 auto}
.chart-legend{font-size:12px;color:var(--muted);margin-top:6px}
.tabs{display:flex;gap:6px;flex-wrap:wrap}
.tabs button[aria-pressed=true]{background:var(--brand);border-color:var(--brand);color:#fff}
ul.tight{margin:6px 0 0;padding-left:20px}
ul.tight li{margin:3px 0}
.sugg{list-style:none;margin:0;padding:0;display:grid;gap:9px}
.sugg li{border:1px solid var(--line);border-left:5px solid var(--muted);border-radius:9px;padding:9px 11px;background:#fff}
.sugg li b{display:block;font-size:14px;margin-bottom:2px}
.sugg li.risk{border-left-color:var(--risk);background:var(--risk-soft)}
.sugg li.warn{border-left-color:var(--warn);background:var(--warn-soft)}
.sugg li.note{border-left-color:var(--brand);background:var(--brand-soft)}
.sugg li.ok{border-left-color:var(--ok);background:var(--ok-soft)}
footer .small{color:var(--muted)}
.check-ok{color:var(--ok);font-weight:700}
.check-bad{color:var(--risk);font-weight:700}
hr.sep{border:none;border-top:1px solid var(--line);margin:14px 0}
@media (max-width:520px){
  .wrap{padding:12px 10px 36px}
  body{font-size:14.5px}
  th,td{padding:6px 7px;font-size:12.5px}
  .table-scroll{max-height:360px}
  .card{padding:12px 11px}
}
@media print{
  .filters,.btn-row,.tabs{display:none}
  body{background:#fff}
  .card{break-inside:avoid;box-shadow:none}
}
</style>
</head>
<body>
<div class="wrap">

<header>
  <div class="syn-banner" role="note">
    <span class="badge syn">合成验收数据 SYNTHETIC</span>
    <p style="margin-top:8px"><b>本报表全部数值来自专门构造的合成验收数据</b>（《2026年10月生产明细.csv》《2026年10月经营补充.xlsx》），
    仅用于交付物验收与口径演示，<b>不代表任何真实企业的经营结果、产能、能耗、价格或发货情况</b>。</p>
    <p class="small" style="margin-bottom:0">发货金额为按“发货量 × 单价”计算的合成收入，<b>不等于利润，也不等于回款</b>。</p>
  </div>
  <h1>生产运行报表 · 2026年10月 <span class="badge brand">工厂运营视角</span></h1>
  <p class="small" id="head-sub">正在载入合成验收数据…</p>
  <div class="meta-list" id="head-meta"></div>
</header>

<section class="card" aria-labelledby="h-filters">
  <div class="card-head">
    <h2 id="h-filters">筛选条件（作用于生产 KPI、图表、排名与明细表）</h2>
    <span class="small">默认值＝完整去重数据范围（96 条记录）</span>
  </div>
  <div class="filters">
    <div class="field">
      <label for="filter-line">产线</label>
      <select id="filter-line" aria-label="按产线筛选生产记录"></select>
    </div>
    <div class="field">
      <label for="filter-shift">班次</label>
      <select id="filter-shift" aria-label="按班次筛选生产记录"></select>
    </div>
    <div class="field">
      <label for="filter-start">开始日期</label>
      <input type="date" id="filter-start" aria-label="生产记录起始日期（含当日）">
    </div>
    <div class="field">
      <label for="filter-end">结束日期</label>
      <input type="date" id="filter-end" aria-label="生产记录结束日期（含当日）">
    </div>
  </div>
  <div class="btn-row">
    <button type="button" id="reset-filters">重置筛选</button>
    <button type="button" id="export-csv" class="primary">导出当前明细 CSV</button>
    <span class="small">导出的 CSV 保留原始 11 个字段名，未记录的停机/电耗留空（不填 0）。</span>
  </div>
  <p class="status" id="status" role="status" aria-live="polite"></p>
</section>

<section class="card" aria-labelledby="h-kpi">
  <div class="card-head">
    <h2 id="h-kpi">关键指标</h2>
    <span class="small">良品率＝合格合计/实际合计；达成率＝实际合计/计划合计；单位电耗＝电耗合计/同范围实际产量合计</span>
  </div>
  <div class="kpis">
    <div class="kpi"><div class="k-label">计划产量</div><div class="k-value"><span id="metric-planned">—</span><span class="k-unit">吨</span></div><div class="k-note" id="note-planned"></div></div>
    <div class="kpi hl"><div class="k-label">实际产量</div><div class="k-value"><span id="metric-actual">—</span><span class="k-unit">吨</span></div><div class="k-note" id="note-actual"></div></div>
    <div class="kpi"><div class="k-label">合格产量（良品）</div><div class="k-value"><span id="metric-good">—</span><span class="k-unit">吨</span></div><div class="k-note">已核对：实际＝合格＋不良</div></div>
    <div class="kpi"><div class="k-label">不良产量</div><div class="k-value"><span id="metric-defective">—</span><span class="k-unit">吨</span></div><div class="k-note" id="note-defective"></div></div>
    <div class="kpi"><div class="k-label">加权良品率</div><div class="k-value"><span id="metric-quality">—</span><span class="k-unit">%</span></div><div class="k-note" id="note-quality"></div></div>
    <div class="kpi"><div class="k-label">计划达成率</div><div class="k-value"><span id="metric-attainment">—</span><span class="k-unit">%</span></div><div class="k-note" id="note-attainment"></div></div>
    <div class="kpi"><div class="k-label">单位电耗</div><div class="k-value"><span id="metric-energy">—</span><span class="k-unit">kWh/吨</span></div><div class="k-note" id="note-energy"></div></div>
    <div class="kpi"><div class="k-label">已知停机</div><div class="k-value"><span id="metric-downtime">—</span><span class="k-unit">分钟</span></div><div class="k-note" id="note-downtime"></div></div>
    <div class="kpi hl"><div class="k-label">当前记录数</div><div class="k-value"><span id="metric-records">—</span><span class="k-unit">条</span></div><div class="k-note">去重后范围内命中</div></div>
  </div>
</section>

<section class="card" aria-labelledby="h-dq">
  <div class="card-head">
    <h2 id="h-dq">数据质量与口径</h2>
    <span class="small">全量口径固定；右侧随筛选变化，两者分开标注</span>
  </div>
  <div class="grid2">
    <div>
      <h3 style="margin-top:0">全量（去重前后）</h3>
      <div class="scroll-x"><table id="dq-full"><caption>来源：生产明细 CSV 全表</caption><tbody></tbody></table></div>
    </div>
    <div>
      <h3 style="margin-top:0">当前筛选内</h3>
      <div class="scroll-x"><table id="dq-current"><caption>随筛选实时更新</caption><tbody></tbody></table></div>
    </div>
  </div>
  <p class="small" id="dq-note"></p>
</section>

<section class="card chart" aria-labelledby="h-c1">
  <div class="card-head"><h2 id="h-c1">产线计划与实际产量对比</h2><span class="small">横向条形，单位：吨；按实际产量降序</span></div>
  <div id="chart-lines"></div>
  <p class="chart-legend">灰色＝计划产量，蓝色＝实际产量；条末标注吨数，左侧标注名次与达成率。零产量记录仍计入计划与实际合计。</p>
</section>

<section class="card chart" aria-labelledby="h-c2">
  <div class="card-head"><h2 id="h-c2">每日产量趋势</h2><span class="small">单位：吨；虚线＝计划，实线＝实际</span></div>
  <div id="chart-trend"></div>
  <p class="chart-legend" id="trend-note"></p>
</section>

<section class="card chart" aria-labelledby="h-c3">
  <div class="card-head">
    <h2 id="h-c3">产线能耗与品质</h2>
    <div class="tabs" role="group" aria-label="选择指标">
      <button type="button" id="tab-energy" aria-pressed="true">单位电耗 kWh/吨</button>
      <button type="button" id="tab-quality" aria-pressed="false">加权良品率 %</button>
    </div>
  </div>
  <div id="chart-metric"></div>
  <p class="chart-legend">柱＝当前筛选内该产线指标；黑色虚线＝Excel《产线目标》中的目标值。良品率图纵轴非零基线，已在图内标注起始值。</p>
</section>

<section class="card" aria-labelledby="h-rank">
  <div class="card-head"><h2 id="h-rank">产线排名与目标差距</h2><span class="small">按实际产量降序；差距＝实际−目标，绿＝优于目标，红＝劣于目标</span></div>
  <div class="scroll-x">
    <table id="rank-table">
      <caption>目标取自 Excel「产线目标」：良品率、产量达成率、单位电耗（kWh/吨）</caption>
      <thead><tr>
        <th class="tl" scope="col">名次/产线</th><th scope="col">记录数</th><th scope="col">计划(吨)</th><th scope="col">实际(吨)</th>
        <th scope="col">合格(吨)</th><th scope="col">不良(吨)</th>
        <th scope="col">良品率 / 目标 / 差距</th><th scope="col">达成率 / 目标 / 差距</th><th scope="col">单位电耗 / 目标 / 差距</th><th scope="col">已知停机(分)</th>
      </tr></thead>
      <tbody id="rank-body"></tbody>
      <tfoot id="rank-foot"></tfoot>
    </table>
  </div>
  <p class="small" id="rank-note"></p>
</section>

<section class="card" aria-labelledby="h-detail">
  <div class="card-head">
    <h2 id="h-detail">生产明细（去重后完整 11 列）</h2>
    <span class="small">点击表头可排序；空白＝未记录（不填 0）；黄色行＝零产量记录</span>
  </div>
  <div class="table-scroll">
    <table id="detail-table">
      <caption id="detail-caption">生产明细</caption>
      <thead><tr id="detail-head"></tr></thead>
      <tbody id="detail-body"></tbody>
    </table>
  </div>
  <div class="empty" id="detail-empty" hidden>当前筛选没有生产记录：KPI 显示“—”，图表与明细表均为空，不会补 0 或估算数值。请调整条件或点击“重置筛选”。</div>
</section>

<section class="card" aria-labelledby="h-ship">
  <div class="card-head"><h2 id="h-ship">发货与收入（合成口径）</h2><span class="small">收入＝逐条发货量 × 单价求和，单位元</span></div>
  <p class="small" id="ship-note" style="margin-top:0"></p>
  <div class="kpis">
    <div class="kpi"><div class="k-label">发货单数</div><div class="k-value"><span id="ship-records">—</span><span class="k-unit">单</span></div></div>
    <div class="kpi"><div class="k-label">发货量</div><div class="k-value"><span id="ship-qty">—</span><span class="k-unit">吨</span></div></div>
    <div class="kpi hl"><div class="k-label">发货收入</div><div class="k-value"><span id="ship-revenue">—</span><span class="k-unit">元</span></div><div class="k-note">≠ 利润，≠ 回款</div></div>
    <div class="kpi"><div class="k-label">加权均价</div><div class="k-value"><span id="ship-price">—</span><span class="k-unit">元/吨</span></div><div class="k-note">收入合计 ÷ 发货量合计</div></div>
  </div>
  <h3>分产线发货</h3>
  <div class="scroll-x">
    <table id="ship-table">
      <thead><tr><th class="tl" scope="col">产线</th><th scope="col">发货单数</th><th scope="col">发货量(吨)</th><th scope="col">收入(元)</th><th scope="col">均价(元/吨)</th><th scope="col">占同范围产量</th></tr></thead>
      <tbody id="ship-body"></tbody>
    </table>
  </div>
  <details id="ship-details"><summary class="small">展开查看发货记录明细（受产线与日期筛选）</summary>
    <div class="table-scroll" style="margin-top:8px">
      <table><thead><tr><th class="tl" scope="col">发货单号</th><th scope="col">日期</th><th class="tl" scope="col">产线</th><th class="tl" scope="col">产品</th><th scope="col">发货量(吨)</th><th scope="col">单价(元/吨)</th><th scope="col">收入(元)</th></tr></thead>
      <tbody id="ship-rows"></tbody></table>
    </div>
  </details>
  <p class="small">发货源数据<b>没有班次维度</b>，因此本报表不对发货做任何班次拆分或分摊。</p>
</section>

<section class="card" aria-labelledby="h-sugg">
  <div class="card-head"><h2 id="h-sugg">分析结论与改进建议</h2><span class="small">全部基于当前筛选范围内可计算的指标</span></div>
  <ul class="sugg" id="suggest"></ul>
</section>

<section class="card" aria-labelledby="h-lim">
  <div class="card-head"><h2 id="h-lim">限制说明与计算口径</h2><span class="small">阅读结论前请先看这里</span></div>
  <div class="grid2">
    <div>
      <h3 style="margin-top:0">已知限制（合成验收样本）</h3>
      <ul class="tight" id="limits"></ul>
    </div>
    <div>
      <h3 style="margin-top:0">《口径说明》原文规则</h3>
      <ul class="tight" id="caliber"></ul>
    </div>
  </div>
</section>

<section class="card" aria-labelledby="h-check">
  <div class="card-head"><h2 id="h-check">口径自检（页内 JS 计算 vs metrics.json）</h2><span class="small">全量范围一致性校验</span></div>
  <div class="scroll-x">
    <table id="check-table"><thead><tr><th class="tl" scope="col">指标</th><th scope="col">metrics.json</th><th scope="col">页内计算</th><th class="tl" scope="col">结果</th></tr></thead><tbody></tbody></table>
  </div>
  <p class="small" id="check-summary"></p>
</section>

<footer class="card">
  <h2 style="font-size:16px">交付文件与说明</h2>
  <ul class="tight" id="files"></ul>
  <hr class="sep">
  <p class="small"><b>合成验收数据声明：</b>本页所有数字、产线名称、产品名称、单价与发货记录均为专门构造的合成验收数据，
  不代表真实企业经营结果，不可用于对外披露、决策或宣传。生成时间 <span id="build-date"></span>，页面完全自包含（无 CDN、无远程字体、无外部图片，图表为内联 SVG），可离线直接打开。</p>
</footer>

</div>

<script>
