</script>
<script>
/*__PAYLOAD__*/
</script>
<script>
(function () {
  'use strict';
  var C = window.FRC, P = window.REPORT_DATA;
  var ROWS = P.rows, TARGETS = P.targets, SHIPS = P.shipments, META = P.meta, METRICS = P.metrics;
  var F = C.fmt;
  function $(id) { return document.getElementById(id); }

  var COLS = [
    { k: 'id', label: '记录编号', num: false },
    { k: 'date', label: '日期', num: false },
    { k: 'line', label: '产线', num: false },
    { k: 'shift', label: '班次', num: false },
    { k: 'product', label: '产品', num: false },
    { k: 'planned', label: '计划产量_吨', num: true },
    { k: 'actual', label: '实际产量_吨', num: true },
    { k: 'good', label: '合格产量_吨', num: true },
    { k: 'defective', label: '不良产量_吨', num: true },
    { k: 'downtime', label: '停机分钟', num: true },
    { k: 'energy', label: '电耗_kWh', num: true }
  ];

  var state = {
    line: 'all', shift: 'all', start: META.period.start, end: META.period.end,
    sortKey: 'id', sortDir: 1, mode: 'energy'
  };

  /* ---- 控件初始化：初始值代表完整去重数据范围 ---- */
  function fillSelect(el, values, allLabel) {
    var html = '<option value="all">' + C.esc(allLabel) + '</option>';
    values.forEach(function (v) { html += '<option value="' + C.esc(v) + '">' + C.esc(v) + '</option>'; });
    el.innerHTML = html;
  }
  var lines = C.uniqueValues(ROWS, 'line'), shifts = C.uniqueValues(ROWS, 'shift');
  fillSelect($('filter-line'), lines, '全部产线（' + lines.length + ' 条）');
  fillSelect($('filter-shift'), shifts, '全部班次');
  var sIn = $('filter-start'), eIn = $('filter-end');
  [sIn, eIn].forEach(function (el) { el.min = META.period.start; el.max = META.period.end; });
  sIn.value = META.period.start; eIn.value = META.period.end;
  $('filter-line').value = 'all';
  $('filter-shift').value = 'all';

  function currentFilter() {
    return { line: state.line, shift: state.shift, start: state.start || null, end: state.end || null };
  }
  function currentRows() { return C.filterRows(ROWS, currentFilter()); }

  function widthOf(id) {
    var el = $(id);
    var w = el.clientWidth || (el.parentNode && el.parentNode.clientWidth) || 640;
    return Math.max(290, Math.min(Math.round(w), 980));
  }

  /* ---- 排序 ---- */
  function sortRows(rows) {
    var k = state.sortKey, dir = state.sortDir;
    return rows.slice().sort(function (a, b) {
      var x = a[k], y = b[k];
      var xn = (x === null || x === undefined), yn = (y === null || y === undefined);
      if (xn && yn) return 0;
      if (xn) return 1;
      if (yn) return -1;
      if (typeof x === 'number' && typeof y === 'number') return (x - y) * dir;
      return String(x).localeCompare(String(y), 'zh-Hans-CN') * dir;
    });
  }

  function gapCell(val, unit, higherBetter) {
    if (!C.isNum(val)) return '<span class="miss">—</span>';
    var good = higherBetter ? val >= 0 : val <= 0;
    return '<span class="' + (good ? 'pos' : 'neg') + '">' + F.signed(val, unit) + '</span>';
  }

  /* ---- 主渲染 ---- */
  function render() {
    var f = currentFilter();
    var rows = currentRows();
    var agg = C.aggregate(rows);
    var lineRows = C.byLine(rows, TARGETS);
    var daily = C.byDate(rows);
    var isEmpty = rows.length === 0;

    /* KPI */
    $('metric-planned').textContent = F.int(agg.planned);
    $('metric-actual').textContent = F.int(agg.actual);
    $('metric-good').textContent = F.int(agg.good);
    $('metric-defective').textContent = F.int(agg.defective);
    $('metric-quality').textContent = C.isNum(agg.quality) ? F.num(agg.quality, 2) : '数据不足';
    $('metric-attainment').textContent = C.isNum(agg.attainment) ? F.num(agg.attainment, 2) : '数据不足';
    $('metric-energy').textContent = C.isNum(agg.specific) ? F.num(agg.specific, 2) : '数据不足';
    $('metric-downtime').textContent = F.int(agg.downtime);
    $('metric-records').textContent = F.int(agg.records);

    $('note-planned').textContent = isEmpty ? '无记录' : F.int(lineRows.length) + ' 条产线参与合计';
    $('note-actual').textContent = isEmpty ? '无记录' : '与计划差 ' + F.signed((agg.actual || 0) - (agg.planned || 0), ' 吨');
    var share = (C.isNum(agg.defective) && C.isNum(agg.actual) && agg.actual > 0)
      ? F.num(agg.defective / agg.actual * 100, 2) + '%' : '—';
    $('note-defective').textContent = isEmpty ? '无记录' : '占实际产量 ' + share;
    $('note-quality').textContent = isEmpty ? '无记录，不做计算' : '合格 ' + F.int(agg.good) + ' ÷ 实际 ' + F.int(agg.actual);
    $('note-attainment').textContent = isEmpty ? '无记录，不做计算' : '实际 ÷ 计划 × 100';
    $('note-energy').textContent = isEmpty ? '无记录，不做计算'
      : '仅 ' + F.int(agg.energyRows) + ' 条可算：' + F.int(agg.energyKwh) + ' kWh ÷ ' + F.int(agg.energyTonnes) + ' 吨';
    $('note-downtime').textContent = isEmpty ? '无记录'
      : '含 ' + F.int(agg.missingDowntime) + ' 条未记录（留空不填 0）';

    /* 数据质量 */
    var dq = METRICS.data_quality;
    var fullRows = [
      ['原始行数', F.int(dq.source_rows) + ' 行', ''],
      ['唯一记录', F.int(dq.unique_rows) + ' 行', '去重后（本表全部统计口径）'],
      ['重复记录', F.int(dq.duplicate_rows) + ' 行', '编号 ' + dq.duplicate_ids.join('、') + '（逐列相同，保留首条）'],
      ['停机未记录', F.int(dq.missing_downtime) + ' 条', '保留缺失，不填零'],
      ['电耗未记录', F.int(dq.missing_energy) + ' 条', '不计入单位电耗'],
      ['零产量记录', dq.zero_output_ids.join('、'), '计入计划/产量/停机，不算该行单位电耗'],
      ['加总一致性', '实际 = 合格 + 不良：' + (META.balanceViolations === 0 ? '全部成立' : '有 ' + META.balanceViolations + ' 条不符'), '']
    ];
    $('dq-full').querySelector('tbody').innerHTML = fullRows.map(function (r) {
      return '<tr><td class="tl"><b>' + C.esc(r[0]) + '</b><div class="small">' + C.esc(r[2]) + '</div></td><td class="tl">' + C.esc(r[1]) + '</td></tr>';
    }).join('');
    var cur = [
      ['命中记录数', F.int(agg.records) + ' 条', '占全量 ' + (agg.records && dq.unique_rows ? F.num(agg.records / dq.unique_rows * 100, 1) : '—') + '%'],
      ['停机未记录（本范围）', F.int(agg.missingDowntime) + ' 条', '对应「已知停机」为部分口径'],
      ['电耗未记录（本范围）', F.int(agg.missingEnergy) + ' 条', '单位电耗覆盖率 ' + (agg.records ? F.num(agg.energyRows / agg.records * 100, 1) : '—') + '%'],
      ['零产量记录（本范围）', agg.zeroRows ? agg.zeroIds.join('、') : '无', '仍计入计划、产量与停机'],
      ['覆盖天数', F.int(daily.length) + ' 天', daily.length ? daily[0].date + ' ~ ' + daily[daily.length - 1].date : '—'],
      ['覆盖产线 / 班次', F.int(lineRows.length) + ' / ' + F.int(C.byShift(rows).length), '当前筛选组合']
    ];
    $('dq-current').querySelector('tbody').innerHTML = cur.map(function (r) {
      return '<tr><td class="tl"><b>' + C.esc(r[0]) + '</b><div class="small">' + C.esc(r[2]) + '</div></td><td class="tl">' + C.esc(r[1]) + '</td></tr>';
    }).join('');
    $('dq-note').innerHTML = '说明：电耗或停机空白表示<b>未记录</b>，本报表保留缺失而不填零，因此「已知停机」「单位电耗」均为已记录部分的口径，真实值可能被低估。'
      + '所有统计均基于按 <code>记录编号</code> 去重（保留首条）后的 ' + F.int(dq.unique_rows) + ' 条记录。';

    /* 图表 */
    $('chart-lines').innerHTML = C.chartLineCompare(lineRows, widthOf('chart-lines'));
    $('chart-trend').innerHTML = C.chartTrend(daily, widthOf('chart-trend'));
    var worst = daily.filter(function (d) { return C.isNum(d.attainment); })
      .sort(function (a, b) { return a.attainment - b.attainment; })[0];
    $('trend-note').innerHTML = isEmpty ? '当前筛选没有记录。'
      : '范围内共 ' + F.int(daily.length) + ' 天，单日达成率最低为 <b>' + C.esc(worst ? worst.date : '—') + '</b>（计划 '
      + F.int(worst ? worst.planned : null) + ' 吨 / 实际 ' + F.int(worst ? worst.actual : null) + ' 吨，达成 '
      + F.pct(worst ? worst.attainment : null) + '），主要由当日零产量班次拖累。';
    $('chart-metric').innerHTML = C.chartLineMetric(lineRows, widthOf('chart-metric'), state.mode);

    /* 排名表 */
    $('rank-body').innerHTML = lineRows.length ? lineRows.map(function (l) {
      return '<tr>' +
        '<td class="tl"><b>' + l.rank + '. ' + C.esc(l.line) + '</b></td>' +
        '<td>' + F.int(l.records) + '</td>' +
        '<td>' + F.int(l.planned) + '</td>' +
        '<td><b>' + F.int(l.actual) + '</b></td>' +
        '<td>' + F.int(l.good) + '</td>' +
        '<td>' + F.int(l.defective) + '</td>' +
        '<td>' + F.pct(l.quality) + ' / ' + F.pct(l.targetQuality) + ' / ' + gapCell(l.gapQuality, ' pp', true) + '</td>' +
        '<td>' + F.pct(l.attainment) + ' / ' + F.pct(l.targetAttainment) + ' / ' + gapCell(l.gapAttainment, ' pp', true) + '</td>' +
        '<td>' + F.num(l.specific, 2) + ' / ' + F.num(l.targetEnergy, 2) + ' / ' + gapCell(l.gapEnergy, '', false) + '</td>' +
        '<td>' + F.int(l.downtime) + (l.missingDowntime ? ' <span class="tag">缺' + l.missingDowntime + '</span>' : '') + '</td>' +
        '</tr>';
    }).join('') : '<tr><td class="tl" colspan="10">当前筛选没有记录，排名与目标差距不计算（不以 0 代替）。</td></tr>';
    $('rank-foot').innerHTML = lineRows.length ? '<tr><th class="tl" scope="row">合计 / 全范围</th><td>' + F.int(agg.records) + '</td><td>'
      + F.int(agg.planned) + '</td><td>' + F.int(agg.actual) + '</td><td>' + F.int(agg.good) + '</td><td>' + F.int(agg.defective) + '</td>'
      + '<td>' + F.pct(agg.quality) + '</td><td>' + F.pct(agg.attainment) + '</td><td>' + F.num(agg.specific, 2) + '</td><td>' + F.int(agg.downtime) + '</td></tr>' : '';
    var missT = lineRows.filter(function (l) { return !C.isNum(l.specific); }).map(function (l) { return l.line; });
    $('rank-note').innerHTML = '差距列：<b>良品率/达成率</b>为正＝优于目标；<b>单位电耗</b>为负＝低于目标（更省电）。'
      + (missT.length ? '当前范围无单位电耗可算记录的产线：' + C.esc(missT.join('、')) + '（显示为“—”）。' : 'pp＝百分点。')
      + (isEmpty ? '当前筛选为空，故不显示排名。' : '');

    /* 明细表 */
    $('detail-head').innerHTML = COLS.map(function (c) {
      var mark = state.sortKey === c.k ? (state.sortDir > 0 ? ' ▲' : ' ▼') : '';
      return '<th scope="col" role="button" tabindex="0" data-key="' + c.k + '" class="' + (c.num ? '' : 'tl') +
        '" aria-label="按' + C.esc(c.label) + '排序">' + C.esc(c.label) + mark + '</th>';
    }).join('');
    var sorted = sortRows(rows);
    $('detail-caption').textContent = '生产明细：当前 ' + F.int(sorted.length) + ' 条（原始 11 列，缺失留空显示为“未记录”）';
    $('detail-body').innerHTML = sorted.length ? sorted.map(function (r) {
      function cell(v, num) {
        if (v === null || v === undefined) return '<td><span class="miss">未记录</span></td>';
        return '<td' + (num ? '' : ' class="tl"') + '>' + (num ? F.int(v) : C.esc(v)) + '</td>';
      }
      return '<tr' + (r.actual === 0 ? ' class="zero-row"' : '') + '>' +
        '<td class="tl">' + C.esc(r.id) + '</td>' +
        '<td class="tl">' + C.esc(r.date) + '</td>' +
        '<td class="tl">' + C.esc(r.line) + '</td>' +
        '<td class="tl">' + C.esc(r.shift) + '</td>' +
        '<td class="tl">' + C.esc(r.product) + '</td>' +
        cell(r.planned, true) + cell(r.actual, true) + cell(r.good, true) + cell(r.defective, true) +
        cell(r.downtime, true) + cell(r.energy, true) + '</tr>';
    }).join('') : '';
    $('detail-empty').hidden = !isEmpty;
    $('detail-table').style.display = isEmpty ? 'none' : '';

    /* 发货：只接受产线 + 日期筛选 */
    var slist = C.shipFilter(SHIPS, f);
    var sa = C.shipAgg(slist);
    var shiftActive = (f.shift && f.shift !== 'all');
    $('ship-note').innerHTML = '发货区受 <b>产线 / 开始日期 / 结束日期</b> 三个筛选影响；'
      + (shiftActive ? '当前班次筛选为 <b>' + C.esc(f.shift) + '</b>，但发货源数据<b>没有班次维度</b>，因此<b>本区数值不随班次变化</b>（不做任何班次分摊）。'
        : '「班次」筛选不影响本区（源数据无班次维度，不假造分配）。')
      + ' 当前命中 <b>' + F.int(sa.records) + '</b> / ' + F.int(SHIPS.length) + ' 单。';
    $('ship-records').textContent = F.int(sa.records);
    $('ship-qty').textContent = F.int(sa.qty);
    $('ship-revenue').textContent = F.int(sa.revenue);
    $('ship-price').textContent = F.num(sa.avgPrice, 2);
    var byLineActual = {};
    lineRows.forEach(function (l) { byLineActual[l.line] = l.actual; });
    $('ship-body').innerHTML = sa.lines.length ? sa.lines.map(function (l) {
      var a = byLineActual[l.line];
      var ratio = (C.isNum(a) && a > 0) ? F.num(l.qty / a * 100, 2) + '%' : '<span class="miss">同范围无产量</span>';
      return '<tr><td class="tl">' + C.esc(l.line) + '</td><td>' + F.int(l.records) + '</td><td>' + F.int(l.qty) + '</td>'
        + '<td>' + F.int(l.revenue) + '</td><td>' + F.num(l.avgPrice, 2) + '</td><td>' + ratio + '</td></tr>';
    }).join('') + '<tr><th class="tl" scope="row">合计</th><td>' + F.int(sa.records) + '</td><td>' + F.int(sa.qty) + '</td><td>'
      + F.int(sa.revenue) + '</td><td>' + F.num(sa.avgPrice, 2) + '</td><td>'
      + (C.isNum(agg.actual) && agg.actual > 0 ? F.num(sa.qty / agg.actual * 100, 2) + '%' : '—') + '</td></tr>'
      : '<tr><td class="tl" colspan="6">当前筛选（产线/日期）没有发货记录。</td></tr>';
    $('ship-rows').innerHTML = slist.length ? slist.map(function (s) {
      return '<tr><td class="tl">' + C.esc(s.id) + '</td><td class="tl">' + C.esc(s.date) + '</td><td class="tl">' + C.esc(s.line)
        + '</td><td class="tl">' + C.esc(s.product) + '</td><td>' + F.int(s.qty) + '</td><td>' + F.int(s.price) + '</td><td>'
        + F.int(s.revenue) + '</td></tr>';
    }).join('') : '<tr><td class="tl" colspan="7">没有发货记录。</td></tr>';
    $('ship-details').hidden = slist.length === 0;

    /* 建议 */
    var sug = C.suggestions(ROWS, rows, lineRows, {
      sourceRows: METRICS.data_quality.source_rows, uniqueRows: METRICS.data_quality.unique_rows,
      duplicateRows: METRICS.data_quality.duplicate_rows, duplicateIds: METRICS.data_quality.duplicate_ids
    });
    $('suggest').innerHTML = sug.map(function (x) {
      return '<li class="' + C.esc(x.tone) + '"><b>' + C.esc(x.title) + '</b>' + C.esc(x.text) + '</li>';
    }).join('');

    /* 状态 */
    $('status').innerHTML = '当前记录数：<b>' + F.int(agg.records) + '</b> 条（' + describeFilter() + '）'
      + (isEmpty ? ' — <b>无匹配记录</b>，指标显示“数据不足/—”，不填 0、不外推。' : '');
  }

  function describeFilter() {
    var p = [];
    p.push((state.line === 'all' ? '全部产线' : state.line));
    p.push((state.shift === 'all' ? '全部班次' : state.shift));
    p.push((state.start || META.period.start) + ' ~ ' + (state.end || META.period.end));
    return C.esc(p.join(' · '));
  }

  /* ---- 事件绑定 ---- */
  $('filter-line').addEventListener('change', function (e) { state.line = e.target.value; render(); });
  $('filter-shift').addEventListener('change', function (e) { state.shift = e.target.value; render(); });
  $('filter-start').addEventListener('change', function (e) { state.start = e.target.value; render(); });
  $('filter-end').addEventListener('change', function (e) { state.end = e.target.value; render(); });
  $('reset-filters').addEventListener('click', function () {
    state.line = 'all'; state.shift = 'all'; state.start = META.period.start; state.end = META.period.end;
    state.sortKey = 'id'; state.sortDir = 1;
    $('filter-line').value = 'all'; $('filter-shift').value = 'all';
    sIn.value = META.period.start; eIn.value = META.period.end;
    render();
    $('status').innerHTML = '已重置为完整去重数据范围（' + F.int(ROWS.length) + ' 条记录）：' + describeFilter() + '。';
  });
  $('export-csv').addEventListener('click', function () {
    var data = sortRows(currentRows());
    var csv = C.csvFor(data);
    var name = '生产明细_筛选导出_' + (state.line === 'all' ? '全部产线' : state.line) + '_'
      + (state.start || META.period.start) + '_' + (state.end || META.period.end) + '.csv';
    var ok = false;
    try {
      var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url; a.download = name; a.style.display = 'none';
      document.body.appendChild(a); a.click();
      setTimeout(function () { URL.revokeObjectURL(url); document.body.removeChild(a); }, 800);
      ok = true;
    } catch (err) {
      try {
        var a2 = document.createElement('a');
        a2.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
        a2.download = name; document.body.appendChild(a2); a2.click(); document.body.removeChild(a2);
        ok = true;
      } catch (err2) { ok = false; }
    }
    $('status').innerHTML = ok
      ? '已按当前筛选生成 CSV：<b>' + F.int(data.length) + '</b> 条记录，字段为原始 11 列；未记录的停机/电耗留空（不填 0）。文件名：<code>' + C.esc(name) + '</code>'
      : '<b>导出失败</b>：当前浏览器阻止了文件下载，请改用“复制”方式或更换浏览器。筛选结果仍为 ' + F.int(data.length) + ' 条。';
  });
  $('tab-energy').addEventListener('click', function () { setMode('energy'); });
  $('tab-quality').addEventListener('click', function () { setMode('quality'); });
  function setMode(m) {
    state.mode = m;
    $('tab-energy').setAttribute('aria-pressed', String(m === 'energy'));
    $('tab-quality').setAttribute('aria-pressed', String(m === 'quality'));
    $('chart-metric').innerHTML = C.chartLineMetric(C.byLine(currentRows(), TARGETS), widthOf('chart-metric'), m);
  }
  $('detail-head').addEventListener('click', function (e) {
    var th = e.target.closest ? e.target.closest('th[data-key]') : null;
    if (th) toggleSort(th.getAttribute('data-key'));
  });
  $('detail-head').addEventListener('keydown', function (e) {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var th = e.target.closest ? e.target.closest('th[data-key]') : null;
    if (th) { e.preventDefault(); toggleSort(th.getAttribute('data-key')); }
  });
  function toggleSort(k) {
    if (state.sortKey === k) state.sortDir = -state.sortDir;
    else { state.sortKey = k; state.sortDir = 1; }
    render();
  }
  var rT = null;
  window.addEventListener('resize', function () {
    if (rT) clearTimeout(rT);
    rT = setTimeout(render, 160);
  });

  /* ---- 静态区：页头、限制、口径、文件、自检 ---- */
  var dq = METRICS.data_quality;
  $('head-sub').textContent = '统计时间范围 ' + META.period.start + ' ~ ' + META.period.end + '（' + F.int(METRICS.daily.length)
    + ' 天）· 4 条产线 · 白班/夜班 · 去重后 ' + F.int(dq.unique_rows) + ' 条生产记录（原始 ' + F.int(dq.source_rows)
    + ' 行，剔除 ' + F.int(dq.duplicate_rows) + ' 行完全重复）· 另有 ' + F.int(METRICS.shipments.records) + ' 条发货记录';
  $('head-meta').innerHTML = [
    ['数据来源', '2026年10月生产明细.csv + 2026年10月经营补充.xlsx（仅这两个上传文件）'],
    ['数据性质', '合成验收数据，不代表真实企业经营结果'],
    ['口径依据', 'Excel「口径说明」8 条规则 +「产线目标」4 条目标'],
    ['页面形态', '自包含单文件，内联 SVG 图表，离线可打开']
  ].map(function (r) { return '<div><span>' + C.esc(r[0]) + '</span>' + C.esc(r[1]) + '</div>'; }).join('');
  $('limits').innerHTML = [
    '样本仅 ' + F.int(METRICS.daily.length) + ' 天 × 4 产线 × 2 班次（去重后 ' + F.int(dq.unique_rows) + ' 条），为<b>合成验收数据</b>，趋势与建议只用于验收演示，不具备经营决策效力。',
    dq.missing_downtime + ' 条停机分钟与 ' + dq.missing_energy + ' 条电耗为“未记录”，按口径保留空白，因此已知停机与单位电耗是<b>已记录部分</b>的口径。',
