+  return ke + pe;
+}
+function angOf(row){
+  let l = 0;
+  for (let i = 0; i < 3; i++) l += MASS[i] * (px(row, i) * vy(row, i) - py(row, i) * vx(row, i));
+  return l;
+}
+function comOf(row){
+  let x = 0, y = 0, m = 0;
+  for (let i = 0; i < 3; i++) { x += MASS[i] * px(row, i); y += MASS[i] * py(row, i); m += MASS[i]; }
+  return Math.hypot(x, y) / m;
