    if (night && day && isNum(night.downtime) && isNum(day.downtime)) {
      out.push({ tone: 'note', title: '夜班已知停机 ' + FMT.int(night.downtime) + ' 分 vs 白班 ' + FMT.int(day.downtime) + ' 分',
        text: '夜班达成率 ' + FMT.pct(night.attainment) + '，白班 ' + FMT.pct(day.attainment) +
