  <div class="scroll-x">
    <table id="check-table"><thead><tr><th class="tl" scope="col">指标</th><th scope="col">metrics.json</th><th scope="col">页内计算</th><th class="tl" scope="col">结果</th></tr></thead><tbody></tbody></table>
