    $('ship-details').hidden = slist.length === 0;

    /* 建议 */
    var sug = C.suggestions(ROWS, rows, lineRows, {
      sourceRows: METRICS.data_quality.source_rows, uniqueRows: METRICS.data_quality.unique_rows,
      duplicateRows: METRICS.data_quality.duplicate_rows, duplicateIds: METRICS.data_quality.duplicate_ids
    });
    $('suggest').innerHTML = sug.map(function (x) {
      return '<li class="' + C.esc(x.tone) + '"><b>' + C.esc(x.title) + '</b>' + C.esc(x.text) + '</li>';
    }).join('');

    /* 状态 */
    $('status').innerHTML = '当前记录数：<b>' + F.int(agg.records) + '</b> 条（' + describeFilter() + '）'
      + (isEmpty ? ' — <b>无匹配记录</b>，指标显示“数据不足/—”，不填 0、不外推。' : '');
  }

  function describeFilter() {
    var p = [];
    p.push((state.line === 'all' ? '全部产线' : state.line));
    p.push((state.shift === 'all' ? '全部班次' : state.shift));
    p.push((state.start || META.period.start) + ' ~ ' + (state.end || META.period.end));
    return C.esc(p.join(' · '));
  }

  /* ---- 事件绑定 ---- */
  $('filter-line').addEventListener('change', function (e) { state.line = e.target.value; render(); });
  $('filter-shift').addEventListener('change', function (e) { state.shift = e.target.value; render(); });
  $('filter-start').addEventListener('change', function (e) { state.start = e.target.value; render(); });
  $('filter-end').addEventListener('change', function (e) { state.end = e.target.value; render(); });
  $('reset-filters').addEventListener('click', function () {
    state.line = 'all'; state.shift = 'all'; state.start = META.period.start; state.end = META.period.end;
    state.sortKey = 'id'; state.sortDir = 1;
    $('filter-line').value = 'all'; $('filter-shift').value = 'all';
    sIn.value = META.period.start; eIn.value = META.period.end;
    render();
    $('status').innerHTML = '已重置为完整去重数据范围（' + F.int(ROWS.length) + ' 条记录）：' + describeFilter() + '。';
  });
  $('export-csv').addEventListener('click', function () {
    var data = sortRows(currentRows());
    var csv = C.csvFor(data);
    var name = '生产明细_筛选导出_' + (state.line === 'all' ? '全部产线' : state.line) + '_'
      + (state.start || META.period.start) + '_' + (state.end || META.period.end) + '.csv';
    var ok = false;
    try {
      var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url; a.download = name; a.style.display = 'none';
      document.body.appendChild(a); a.click();
      setTimeout(function () { URL.revokeObjectURL(url); document.body.removeChild(a); }, 800);
      ok = true;
    } catch (err) {
      try {
        var a2 = document.createElement('a');
        a2.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
        a2.download = name; document.body.appendChild(a2); a2.click(); document.body.removeChild(a2);
        ok = true;
      } catch (err2) { ok = false; }
    }
    $('status').innerHTML = ok
      ? '已按当前筛选生成 CSV：<b>' + F.int(data.length) + '</b> 条记录，字段为原始 11 列；未记录的停机/电耗留空（不填 0）。文件名：<code>' + C.esc(name) + '</code>'
      : '<b>导出失败</b>：当前浏览器阻止了文件下载，请改用“复制”方式或更换浏览器。筛选结果仍为 ' + F.int(data.length) + ' 条。';
  });
  $('tab-energy').addEventListener('click', function () { setMode('energy'); });
  $('tab-quality').addEventListener('click', function () { setMode('quality'); });
  function setMode(m) {
    state.mode = m;
    $('tab-energy').setAttribute('aria-pressed', String(m === 'energy'));
    $('tab-quality').setAttribute('aria-pressed', String(m === 'quality'));
    $('chart-metric').innerHTML = C.chartLineMetric(C.byLine(currentRows(), TARGETS), widthOf('chart-metric'), m);
  }
  $('detail-head').addEventListener('click', function (e) {
    var th = e.target.closest ? e.target.closest('th[data-key]') : null;
    if (th) toggleSort(th.getAttribute('data-key'));
  });
  $('detail-head').addEventListener('keydown', function (e) {
    if (e.key !== 'Enter' && e.key !== ' ') return;
    var th = e.target.closest ? e.target.closest('th[data-key]') : null;
    if (th) { e.preventDefault(); toggleSort(th.getAttribute('data-key')); }
  });
  function toggleSort(k) {
    if (state.sortKey === k) state.sortDir = -state.sortDir;
    else { state.sortKey = k; state.sortDir = 1; }
    render();
  }
  var rT = null;
  window.addEventListener('resize', function () {
    if (rT) clearTimeout(rT);
    rT = setTimeout(render, 160);
  });

  /* ---- 静态区：页头、限制、口径、文件、自检 ---- */
  var dq = METRICS.data_quality;
  $('head-sub').textContent = '统计时间范围 ' + META.period.start + ' ~ ' + META.period.end + '（' + F.int(METRICS.daily.length)
    + ' 天）· 4 条产线 · 白班/夜班 · 去重后 ' + F.int(dq.unique_rows) + ' 条生产记录（原始 ' + F.int(dq.source_rows)
    + ' 行，剔除 ' + F.int(dq.duplicate_rows) + ' 行完全重复）· 另有 ' + F.int(METRICS.shipments.records) + ' 条发货记录';
  $('head-meta').innerHTML = [
