    ['口径依据', 'Excel「口径说明」8 条规则 +「产线目标」4 条目标'],
    ['页面形态', '自包含单文件，内联 SVG 图表，离线可打开']
  ].map(function (r) { return '<div><span>' + C.esc(r[0]) + '</span>' + C.esc(r[1]) + '</div>'; }).join('');
  $('limits').innerHTML = [
    '样本仅 ' + F.int(METRICS.daily.length) + ' 天 × 4 产线 × 2 班次（去重后 ' + F.int(dq.unique_rows) + ' 条），为<b>合成验收数据</b>，趋势与建议只用于验收演示，不具备经营决策效力。',
    dq.missing_downtime + ' 条停机分钟与 ' + dq.missing_energy + ' 条电耗为“未记录”，按口径保留空白，因此已知停机与单位电耗是<b>已记录部分</b>的口径。',
    '单位电耗只覆盖“电耗已记录且实际产量>0”的 ' + F.int(METRICS.totals.energy_eligible_rows) + ' 条记录（' + F.int(METRICS.totals.energy_eligible_actual_tonnes) + ' 吨）。',
    '发货数据没有班次维度，也不含客户、成本、费用、税费与账期，<b>无法推导利润或回款</b>；发货与生产的产量比值仅作产销衔接参考。',
    '源数据无停机原因、缺陷类型、设备代码等字段，改进建议只能基于现有可计算指标给出方向，不能定位具体故障根因。'
  ].map(function (t) { return '<li>' + t + '</li>'; }).join('');
  $('caliber').innerHTML = META.caliberRules.map(function (t) { return '<li>' + C.esc(t) + '</li>'; }).join('');
  $('files').innerHTML = [
    '<code>factory_report.html</code>：本报表，单文件自包含，双击即可离线打开；筛选、排序、导出均为本地脚本，不联网。',
    '<code>cleaned_production.csv</code>：去重后的生产明细（原始 11 列与字段名，缺失留空，保留零产量记录 ' + dq.zero_output_ids.join('、') + '）。',
    '<code>metrics.json</code>：机器可核对的全量统计（schema_version 1，synthetic=true，per_line 按实际产量降序，daily 按日期升序，百分比为 0–100 数值）。',
    '<code>analyze_production.py</code> / <code>build_report.py</code>：可复核的计算与构建脚本；<code>progress.md</code>：数据来源确认与工作记录。'
  ].map(function (t) { return '<li>' + t + '</li>'; }).join('');

  function check(label, jsonVal, pageVal, dec) {
    var okv;
    if (jsonVal === null || pageVal === null) okv = (jsonVal === pageVal);
    else okv = Math.abs(jsonVal - pageVal) < Math.pow(10, -(dec || 2)) / 2 + 1e-9;
    return { label: label, j: jsonVal, p: pageVal, ok: okv };
  }
  function runSelfCheck() {
    var full = C.aggregate(ROWS);
    var sa = C.shipAgg(SHIPS);
    var t = METRICS.totals, sm = METRICS.shipments;
    var items = [
      ['去重后记录数（条）', dq.unique_rows, full.records, 0],
      ['计划产量（吨）', t.planned_tonnes, full.planned, 0],
      ['实际产量（吨）', t.actual_tonnes, full.actual, 0],
      ['合格产量（吨）', t.good_tonnes, full.good, 0],
      ['不良产量（吨）', t.defective_tonnes, full.defective, 0],
      ['加权良品率（%）', t.weighted_quality_pct, full.quality, 2],
      ['计划达成率（%）', t.attainment_pct, full.attainment, 2],
      ['单位电耗（kWh/吨）', t.specific_energy_kwh_per_tonne, full.specific, 2],
      ['电耗可算记录数（条）', t.energy_eligible_rows, full.energyRows, 0],
      ['已知停机（分钟）', t.known_downtime_minutes, full.downtime, 0],
      ['发货量（吨）', sm.quantity_tonnes, sa.qty, 0],
      ['发货收入（元）', sm.revenue_yuan, sa.revenue, 0]
    ];
    var pass = 0;
    $('check-table').querySelector('tbody').innerHTML = items.map(function (r) {
      var c = check(r[0], r[1], r[2], r[3]);
      if (c.ok) pass++;
      return '<tr><td class="tl">' + C.esc(c.label) + '</td><td>' + F.num(c.j, (c.j % 1 === 0 ? 0 : 2)) + '</td><td>'
        + F.num(c.p, (c.p % 1 === 0 ? 0 : 2)) + '</td><td class="tl"><span class="' + (c.ok ? 'check-ok' : 'check-bad') + '">'
        + (c.ok ? '一致' : '不一致') + '</span></td></tr>';
    }).join('');
    $('check-summary').innerHTML = '页内 JS 与 <code>metrics.json</code> 在全量范围下比对 ' + items.length + ' 项：<b>' + pass + '/' + items.length + '</b> 一致。'
      + '（本页所有数值均为合成验收数据）';
  }

  $('build-date').textContent = META.buildDate;
  runSelfCheck();
  render();
})();
</script>
</body>
