    ];
    $('dq-current').querySelector('tbody').innerHTML = cur.map(function (r) {
      return '<tr><td class="tl"><b>' + C.esc(r[0]) + '</b><div class="small">' + C.esc(r[2]) + '</div></td><td class="tl">' + C.esc(r[1]) + '</td></tr>';
    }).join('');
    $('dq-note').innerHTML = '说明：电耗或停机空白表示<b>未记录</b>，本报表保留缺失而不填零，因此「已知停机」「单位电耗」均为已记录部分的口径，真实值可能被低估。'
      + '所有统计均基于按 <code>记录编号</code> 去重（保留首条）后的 ' + F.int(dq.unique_rows) + ' 条记录。';

    /* 图表 */
    $('chart-lines').innerHTML = C.chartLineCompare(lineRows, widthOf('chart-lines'));
    $('chart-trend').innerHTML = C.chartTrend(daily, widthOf('chart-trend'));
    var worst = daily.filter(function (d) { return C.isNum(d.attainment); })
      .sort(function (a, b) { return a.attainment - b.attainment; })[0];
    $('trend-note').innerHTML = isEmpty ? '当前筛选没有记录。'
      : '范围内共 ' + F.int(daily.length) + ' 天，单日达成率最低为 <b>' + C.esc(worst ? worst.date : '—') + '</b>（计划 '
      + F.int(worst ? worst.planned : null) + ' 吨 / 实际 ' + F.int(worst ? worst.actual : null) + ' 吨，达成 '
      + F.pct(worst ? worst.attainment : null) + '），主要由当日零产量班次拖累。';
